 ['a message on a loopback SMTP server: send_message sends Bcc recipients but not the Bcc header', "import socketserver, threading, smtplib\nfrom email.message import EmailMessage\nseen = {}\nclass H(socketserver.StreamRequestHandler):\n    def handle(self):\n        w = lambda s: self.wfile.write(s.encode() + b'\\r\\n')\n        w('220 local test server')\n        rcpts = []; data = []\n        while True:\n            line = self.rfile.readline().decode().rstrip('\\r\\n')\n            if not line: break\n            cmd = line.split(' ')[0].upper()\n            if cmd in ('EHLO', 'HELO'): w('250 ok')\n            elif cmd == 'MAIL': seen['from'] = line; w('250 ok')\n            elif cmd == 'RCPT': rcpts.append(line.split(':', 1)[1]); w('250 ok')\n            elif cmd == 'DATA':\n                w('354 go')\n                while True:\n                    l = self.rfile.readline().decode().rstrip('\\r\\n')\n                    if l == '.': break\n                    data.append(l)\n                seen['rcpts'] = rcpts; seen['data'] = data; w('250 queued')\n            elif cmd == 'QUIT': w('221 bye'); break\n            else: w('250 ok')\nsrv = socketserver.TCPServer(('127.0.0.1', 0), H)\nthreading.Thread(target=srv.handle_request, daemon=True).start()\nm = EmailMessage()\nm['From'] = 'sender@example.com'; m['To'] = 'recipient@example.com'\nm['Cc'] = 'friend@example.com'; m['Bcc'] = 'otherfriend@example.com, someoneelse@example.com'\nm['Subject'] = 'Subject line'; m.set_content('Body of the email')\nwith smtplib.SMTP('127.0.0.1', srv.server_address[1]) as s:\n    print(s.send_message(m))\nsrv.server_close()\nprint(seen['rcpts'])\nprint(any(l.lower().startswith('bcc') for l in seen['data']), any(l.startswith('Cc:') for l in seen['data']))", "{}\n['<recipient@example.com>', '<otherfriend@example.com>', '<someoneelse@example.com>', '<friend@example.com>']\nFalse True"],
