 ['a loopback stand-in for ntfy receives the POST with its headers and serves one JSON object per line', "import http.server, threading, json, urllib.request as r\nlog = []\nclass H(http.server.BaseHTTPRequestHandler):\n    def do_POST(self):\n        n = int(self.headers['Content-Length']); log.append((self.command, self.path, self.rfile.read(n).decode(), self.headers['Title'], self.headers['Priority'], self.headers['Tags']))\n        self.send_response(200); self.end_headers(); self.wfile.write(b'{}')\n    def do_GET(self):\n        body = ''.join(json.dumps(d, separators=(',', ':')) + '\\n' for d in ({'id': 'a1', 'event': 'open'}, {'id': 'a2', 'event': 'message', 'message': 'Hello, world!'}, {'id': 'a3', 'event': 'message', 'message': 'The rent is too high!', 'priority': 5, 'tags': ['warning']})).encode()\n        self.send_response(200); self.send_header('Content-Length', str(len(body))); self.end_headers(); self.wfile.write(body)\n    def log_message(self, *a): pass\nsrv = http.server.HTTPServer(('127.0.0.1', 0), H)\nthreading.Thread(target=srv.serve_forever, daemon=True).start()\nbase = 'http://127.0.0.1:%d/AlSweigartZPgxBQ42' % srv.server_address[1]\nwith r.urlopen(r.Request(base, data=b'The rent is too high!', headers={'Title': 'Important', 'Tags': 'warning', 'Priority': '5'})) as resp:\n    print(resp.status)\nprint(log)\nwith r.urlopen(base + '/json?poll=1') as resp:\n    text = resp.read().decode()\nsrv.shutdown()\nmsgs = [json.loads(l) for l in text.splitlines()]\nprint(len(msgs), [m['message'] for m in msgs if m['event'] == 'message'])\nprint(msgs[1].get('priority'), msgs[2].get('priority'))\ntry:\n    json.loads(text)\nexcept json.JSONDecodeError as e:\n    print(type(e).__name__)", "200\n[('POST', '/AlSweigartZPgxBQ42', 'The rent is too high!', 'Important', '5', 'warning')]\n3 ['Hello, world!', 'The rent is too high!']\nNone 5\nJSONDecodeError"],
 ["the book's poll response parses line by line and not as one document; absent keys raise KeyError", 'import json\ntext = \'{"id":"1jnHKeFNqwnS","time":1797823340,"expires":1797866540,"event":"message","topic":"AlSweigartZPgxBQ42","message":"Hello, world!"}\\n{"id":"wZ22cjyKXw1F","time":1797823712,"expires":1797866912,"event":"message","topic":"AlSweigartZPgxBQ42","title":"Important: Read this!","message":"The rent is too high!","priority":5,"tags":["warning","neutral_face"]}\\n\'\ntry:\n    json.loads(text)\nexcept json.JSONDecodeError as e:\n    print(type(e).__name__ + \': \' + str(e))\nnotifications = []\nfor json_text in text.splitlines():\n    notifications.append(json.loads(json_text))\nprint(notifications[0][\'message\'])\nprint(notifications[1][\'message\'])\nprint(notifications[1][\'tags\'], notifications[1][\'priority\'])\ntry:\n    notifications[0][\'title\']\nexcept KeyError as e:\n    print(\'KeyError\', e)\nprint(notifications[0].get(\'title\'), notifications[0].get(\'priority\', 3))\nprint(notifications[1][\'time\'] - notifications[0][\'time\'], notifications[1][\'expires\'] - notifications[1][\'time\'])', "JSONDecodeError: Extra data: line 2 column 1 (char 134)\nHello, world!\nThe rent is too high!\n['warning', 'neutral_face'] 5\nKeyError 'title'\nNone 3\n372 43200"],
